201	    /**
202	     * The owner's membership level, a number from 1 to 3 fixed at creation. Starts at 1; add 1 when an
203	     * email is present; add 1 when {@code namesakeCount} is 0; capped at 3. Level 4 is reserved for
204	     * tenure and is never produced here.
205	     */
206	    public int getMembershipLevel() {
207	        int level = 1;
208	        boolean hasEmail = this.email != null && !this.email.isBlank();
209	        if (hasEmail) {
210	            level++;
211	        }
212	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
213	        if (unique) {
214	            level++;
215	        }
216	        return Math.min(level, 3);
217	    }
